defaultsEditorPlugin={update:function(pluginName){var pluginNode=jevjq(pluginName);while(pluginNode.firstChild){pluginNode.removeChild(pluginNode.firstChild)}},optgroup:function(pluginNode,label){var group=jevjq("<optgroup/>",{label:label});jevjq(pluginNode).append(group);return group},node:function(parent,label,value){var optnode=jevjq('<option value="'+label+":"+value+'">'+label+"</option>");jevjq(parent).append(optnode)},insert:function(fieldName,pluginNode){var sel=jevjq("#"+pluginNode+" option:selected");if(jevjq("#"+pluginNode).selectedIndex==0)return true;var textToInsert="{{"+sel.val()+"}}";$result=jInsertEditorText(textToInsert,fieldName);jevjq(pluginNode).selectedIndex=0;sel.each(function(index,selel){jQuery(selel).attr("selected",false)});return false},inject:function(fieldName,textToInsert){try{Joomla.editors.instances[fieldName].setValue("")}catch(e){try{document.getElementById(fieldName).value=""}catch(e){}}$result=jInsertEditorText(textToInsert,fieldName);return false},extract:function(fieldName){try{return Joomla.editors.instances[fieldName].getValue()}catch(e){try{return document.getElementById(fieldName).value}catch(e){}}return""}};